static void
test_sign_self(const int8_t *f, const int8_t *g,
	const int8_t *F, const int8_t *G, const uint16_t *h_src,
	unsigned logn, uint8_t *tmp, size_t n_sig)
{
	unsigned i;
	size_t n;
	inner_shake256_context rng;
	char buf[20];
	uint16_t *h, *hm, *hm2;
	int16_t *sig;
	uint8_t *tt;
	fpr *expanded_key;

	n = (size_t)1 << logn;
	h = (uint16_t *)tmp;
	hm = h + n;
	sig = (int16_t *)(hm + n);
	hm2 = (uint16_t *)sig;
	tt = (uint8_t *)(sig + n);
	if (logn == 1) {
		tt += 4;
	}

	memcpy(h, h_src, n * sizeof *h);
	Zf(to_ntt_monty)(h, logn);

	/* sprintf(buf, "sign %u", logn); */
	memcpy(buf, "sign 0", 7);
	buf[5] = '0' + logn;

	inner_shake256_init(&rng);
	inner_shake256_inject(&rng, (uint8_t *)buf, strlen(buf));
	inner_shake256_flip(&rng);

	print_debug(("\nexpand_key (n=%zu):\n", n));
	fflush(stdout);
	expanded_key = (fpr *)tt;
	tt = (uint8_t *)expanded_key + (sizeof(fpr) * logn + 5*sizeof(fpr)) * n;
	Zf(expand_privkey)(expanded_key, f, g, F, G, logn, tt);
	print_debug(("\nexpand_key (n=%zu) ok!\n", n));
	for (i = 0; i < (logn + 5) * n; i++)
		print_fpapprox_buf(&expanded_key[i], 1, "\t");
	

	print_debug(("\nTree sign (n=%zu):\n", n));
	fflush(stdout);
	for (i = 0; i < n_sig; i ++) {
		uint8_t msg[10];  /* nonce + plain */
		inner_shake256_context sc;

		inner_shake256_extract(&rng, msg, sizeof msg);

		inner_shake256_init(&sc);
		inner_shake256_inject(&sc, msg, sizeof msg);
		inner_shake256_flip(&sc);
		Zf(hash_to_point_vartime)(&sc, hm, logn);
		Zf(sign_tree)(sig, &rng, expanded_key, hm, logn, tt);
        printf("m_%d", i);
		print_buf((uint8_t*)msg, sizeof msg, "");
		fflush(stdout);
		printf("sig_%d", i);
		print_buf((uint8_t*)sig, n, "");
		fflush(stdout);
		if (!Zf(verify_raw)(hm, sig, h, logn, tt)) {
			fprintf(stderr, "self signature (dyn) not verified\n");
			exit(EXIT_FAILURE);
		}

		
	}

	printf(" ");
	fflush(stdout);
}

static void
test_sign(size_t n_sig)
{
	uint8_t *tmp;
	size_t tlen;

	printf("Test sign: ");
	fflush(stdout);

	tlen = 178176 << 1;
	tmp = xmalloc(tlen);

	test_sign_self(ntru_f_1024, ntru_g_1024, ntru_F_1024, ntru_G_1024,
		ntru_h_1024, 10, tmp, n_sig);
	printf("\n\tn = 10 done\n");
	fflush(stdout);

	xfree(tmp);

	printf("done.\n");
	fflush(stdout);
}

